<!-- CLIENT-SIDE SCRIPT FOR INTERACTIVE MODULES -->
<script>
  // Interactive Sentence Translation State
  const selectedWords = [];
  const correctAnswer = ["Bapak", "nembe", "dhahar", "sekul"];

  function pickTile(btn, word) {
    if (btn.dataset.selected === "true") return;

    btn.dataset.selected = "true";
    btn.classList.add("opacity-40", "pointer-events-none");

    selectedWords.push({ word, btnRef: btn });
    renderSlots();
  }

  function removeSlot(index) {
    const item = selectedWords.splice(index, 1)[0];
    if (item && item.btnRef) {
      item.btnRef.dataset.selected = "false";
      item.btnRef.classList.remove("opacity-40", "pointer-events-none");
    }
    renderSlots();
  }

  function renderSlots() {
    const container = document.getElementById("target-slots");
    const placeholder = document.getElementById("slot-placeholder");

    if (selectedWords.length === 0) {
      container.innerHTML = '<span id="slot-placeholder" class="font-body-sm text-body-sm text-outline italic px-2">Pilih kata di bawah ini...</span>';
      return;
    }

    container.innerHTML = "";
    selectedWords.forEach((item, idx) => {
      const chip = document.createElement("button");
      chip.className = "px-3.5 py-1.5 rounded-md bg-primary text-on-primary font-label-md text-label-md flex items-center gap-1.5 sticker-sm animate-fadeIn";
      chip.innerHTML = `<span>${item.word}</span> <svg class="w-3.5 h-3.5 fill-current opacity-80" viewBox="0 0 24 24"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>`;
      chip.onclick = () => removeSlot(idx);
      container.appendChild(chip);
    });
  }

  function checkAnswer() {
    const feedbackBox = document.getElementById("feedback-box");
    const feedbackText = document.getElementById("feedback-text");
    const currentWords = selectedWords.map(i => i.word);

    feedbackBox.classList.remove("hidden", "bg-tertiary-tint", "text-tertiary", "bg-secondary-tint", "text-secondary");

    const isMatch = currentWords.length === correctAnswer.length &&
      currentWords.every((val, index) => val === correctAnswer[index]);

    if (isMatch) {
      feedbackBox.classList.add("bg-primary-tint", "text-primary");
      feedbackText.innerHTML = "<strong>Tepat Sekali!</strong> 'Bapak nembe dhahar sekul' merupakan tatakrama Krama Inggil.";
    } else {
      feedbackBox.classList.add("bg-secondary-tint", "text-secondary");
      feedbackText.innerHTML = "<strong>Kurang Tepat:</strong> Urutan atau kata Krama Alus belum tepat. Ingat: mangan menjadi dhahar.";
    }
  }

  function resetSim() {
    selectedWords.forEach(item => {
      if (item.btnRef) {
        item.btnRef.dataset.selected = "false";
        item.btnRef.classList.remove("opacity-40", "pointer-events-none");
      }
    });
    selectedWords.length = 0;
    renderSlots();
    document.getElementById("feedback-box").classList.add("hidden");
  }

  // Interactive Aksara Inspector
  function inspectAksara(char, phonetic, example, philosophy) {
    document.getElementById("disp-char").textContent = char;
    document.getElementById("disp-phonetic").textContent = phonetic;
    document.getElementById("disp-example").textContent = "Contoh: " + example;
    document.getElementById("disp-philosophy").textContent = "Makna filosofis: " + philosophy;

    // Smooth animation trigger
    const card = document.getElementById("aksara-detail");
    card.classList.add("scale-[0.99]");
    setTimeout(() => card.classList.remove("scale-[0.99]"), 150);
  }

  // TTS via Web Speech API (suara Jawa bila tersedia, fallback Indonesia)
  function speakText(text) {
    if (!('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'jv-ID';
    const voices = window.speechSynthesis.getVoices();
    const jv = voices.find(v => v.lang && v.lang.startsWith('jv'));
    if (jv) u.voice = jv; else u.lang = 'id-ID';
    window.speechSynthesis.speak(u);
  }
